data.solution:
import numpy as np


def log_ratio_db(I1, I2, eps=1e-8):
    I1 = np.asarray(I1, dtype=float)
    I2 = np.asarray(I2, dtype=float)
    return 10.0 * np.log10((I1 + eps) / (I2 + eps))


def change_mask(I1, I2, threshold_db, eps=1e-8):
    r = log_ratio_db(I1, I2, eps=eps)
    return np.abs(r) > float(threshold_db)
